"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[63543],{20963:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JumpTransitionController","desc":"Renders the jump transition from the phase broadcast:\\n\\n- **Engulf**: the train front fires a blue laser. A small black hole appears\\n  at its tip, grows to the template\'s scale, then glides in and stops\\n  centred on the full train (built platforms plus their ghosts).\\n- **InWormhole**: the train sits inside the hole while the server swaps the\\n  biome. The template\'s speed lines, camera shake and a wider FOV sell the\\n  speed.\\n- **Exit**: the hole speeds past the train back and shrinks away.\\n\\nEvery motion lasts exactly its phase (`JumpDriveConfig.Transition` sets\\nboth), and a phase that arrives early snaps the hole to where that phase\\nstarts, so the biome never swaps in view.\\n\\nNothing here takes movement control. The shake and FOV are offsets on top of\\nwhatever the camera scripts write (see `bindCamera`), so they never drift,\\nand the jump Janitor removes them.","realm":["Client"],"source":{"line":26,"path":"src/StarterPlayer/StarterPlayerScripts/JumpTransitionController.client.luau"}}')}}]);